"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useRef, useState, useTransition } from "react";
import { COLUMNS, moveFor, type Move } from "@/lib/board";
import type { Status } from "@/lib/types";

/** "Move to…" for one card. Maps a column move onto the existing decision actions; the API validates and audits it. */
export function DecisionMove({ id, title, status, editHref }: { id: string; title: string; status: Status; editHref: string }) {
  const router = useRouter();
  const dialog = useRef<HTMLDialogElement>(null);
  const [move, setMove] = useState<Extract<Move, { kind: "action" }> | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [why, setWhy] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const targets = COLUMNS.filter((c) => c.status !== status);

  function pick(to: Status) {
    const m = moveFor(status, to);
    if (!m) return;
    if (m.kind === "blocked") { setNotice(m.message); return; }
    if (m.kind === "edit") { router.push(editHref); return; }
    setNotice(null); setError(null); setWhy(""); setMove(m);
    dialog.current?.showModal();
  }

  function submit() {
    if (!move) return;
    if (move.required && !why.trim()) { setError("Add a short reason. It goes into the audit trail."); return; }
    start(async () => {
      const res = await fetch(`/api/requirements/${id}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: move.action, rationale: why.trim() || undefined }) });
      const body = (await res.json().catch(() => null)) as { ok?: boolean; error?: string } | null;
      if (!res.ok || !body?.ok) { setError(body?.error ?? "The decision could not be saved. Try again."); return; }
      dialog.current?.close();
      router.refresh();
    });
  }

  return (
    <div className="mt-3">
      <label className="sr-only" htmlFor={`move-${id}`}>Move {title} to</label>
      <select id={`move-${id}`} value="" onChange={(e) => pick(e.target.value as Status)} disabled={pending}
        className="h-8 w-full border border-line bg-white px-2 text-[12px] text-ink-2 hover:border-ink">
        <option value="" disabled>Move to…</option>
        {targets.map((c) => <option key={c.status} value={c.status}>{c.title}</option>)}
      </select>
      {notice && <p role="status" className="mt-2 text-[12px] text-ink-2">{notice} {status === "approved" || status === "rejected" ? null : <Link href={editHref} className="text-blue hover:underline">Open card</Link>}</p>}
      <dialog ref={dialog} aria-labelledby={`move-title-${id}`} className="m-auto w-[min(480px,calc(100vw-32px))] border border-line p-6 text-ink backdrop:bg-ink/50">
        <h2 id={`move-title-${id}`} className="text-[20px] font-light">{move?.title}</h2>
        <p className="mt-1 text-[14px] text-ink-2">{title}</p>
        <label className="mt-4 flex flex-col gap-1 text-[13px] font-medium">
          {move?.prompt}
          <textarea value={why} onChange={(e) => setWhy(e.target.value)} rows={3} maxLength={1000} className="border border-line p-2 text-[14px] font-normal focus:border-ink" />
        </label>
        {error && <p role="alert" className="mt-2 text-[13px] text-danger">{error}</p>}
        <div className="mt-5 flex justify-end gap-3">
          <button type="button" className="btn-outline btn-sm" onClick={() => dialog.current?.close()} disabled={pending}>Cancel</button>
          <button type="button" className="btn-primary btn-sm" onClick={submit} disabled={pending}>{pending ? "Saving…" : move?.submit}</button>
        </div>
      </dialog>
    </div>
  );
}

import Link from "next/link";
import { COLUMNS } from "@/lib/board";
import { boardCards, type Viewer } from "@/lib/gate";
import { moscowFor } from "@/lib/moscow";
import { ConflictBadge, QuadrantBadge, QuickWinBadge } from "./ui";
import { DecisionMove } from "./DecisionMove";

const fmt = (n: number) => n.toLocaleString("en-US");

/**
 * Decision board (from Vishwa's feature_v): one column per decision status, so the PM sees where every
 * requirement is in the workflow. The Requirements tab groups by priority; this tab groups by decision.
 */
export async function DecisionBoard({ viewer, vehicle }: { viewer: Viewer; vehicle: { code: string; name: string } }) {
  const cards = await boardCards(viewer, [vehicle]);
  const count = (...s: string[]) => cards.filter((c) => s.includes(c.status)).length;
  const href = (id: string) => `/vehicles/${vehicle.code}?req=${encodeURIComponent(id)}#decision-card`;

  return (
    <section aria-labelledby="decision-board-heading" data-testid="decision-board">
      <div className="mb-6 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h2 id="decision-board-heading" className="headline text-[28px]">Decision board</h2>
          <p className="mt-1 text-[14px] text-ink-2">The AI proposes; you decide. Every move is recorded in the audit trail.</p>
        </div>
        <dl className="grid grid-cols-2 gap-px border border-line bg-line sm:grid-cols-4" aria-label="Requirement counts">
          {[["Awaiting review", count("proposed", "edited"), "text-blue"], ["Needs validation", count("validate"), ""], ["Approved", count("approved"), ""], ["Total", cards.length, ""]].map(([label, n, tone]) => (
            <div key={label as string} className="bg-white px-5 py-3">
              <dt className="text-[12px] text-ink-3">{label}</dt>
              <dd className={`text-[24px] font-light tabular-nums ${tone}`}>{fmt(n as number)}</dd>
            </div>
          ))}
        </dl>
      </div>
      {cards.length === 0 && <p role="status" className="mb-4 border border-line px-4 py-3 text-[14px] text-ink-2">No requirements with evidence in {viewer.label}.</p>}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5">
        {COLUMNS.map((col) => {
          const rows = cards.filter((c) => c.status === col.status).sort((a, b) => b.priority - a.priority);
          return (
            <section key={col.status} aria-label={col.title} data-testid={`decision-${col.status}`} className="flex min-w-0 flex-col border-t-[3px] border-ink bg-mist">
              <div className="flex items-baseline justify-between gap-2 px-3 pt-3">
                <h3 className="text-[12px] font-bold uppercase tracking-[0.1em] text-ink">{col.title}</h3>
                <span className="text-[12px] tabular-nums text-ink-3" aria-label={`${rows.length} requirements`}>{rows.length}</span>
              </div>
              <p className="px-3 pb-2 text-[12px] text-ink-3">{col.hint}</p>
              <ul className="flex flex-col gap-2 px-2 pb-2">
                {rows.map((c) => {
                  const m = moscowFor(c.priority);
                  return (
                    <li key={c.id} data-testid="decision-card" data-requirement-id={c.id} className="border border-line bg-white p-3">
                      <Link href={href(c.id)} className="block hover:text-blue">
                        <span className={`text-[11px] font-bold uppercase tracking-[0.08em] ${m.text}`}>{m.label}</span>
                        <span className="mt-1 block text-[14px] leading-snug [overflow-wrap:anywhere]">{c.title}</span>
                      </Link>
                      <div className="mt-2 flex flex-wrap items-center gap-1.5 text-[12px] text-ink-3">
                        <QuadrantBadge q={c.quadrant} />
                        {c.kind === "quick_win" && <QuickWinBadge />}
                        {c.kind === "market_conflict" && <ConflictBadge />}
                        {c.challenged && <span className="text-challenge">Challenged</span>}
                      </div>
                      <p className="mt-2 flex justify-between text-[12px] tabular-nums text-ink-3">
                        <span>Priority {c.priority} · Confidence {c.confidence}</span>
                        <span>{c.comments === null ? "Survey only" : `${fmt(c.comments)} comments`}</span>
                      </p>
                      <DecisionMove id={c.id} title={c.title} status={c.status} editHref={href(c.id)} />
                    </li>
                  );
                })}
                {rows.length === 0 && <li className="border border-dashed border-line px-3 py-4 text-center text-[12px] text-ink-3">None</li>}
              </ul>
            </section>
          );
        })}
      </div>
    </section>
  );
}

import { expect, test } from '@playwright/test';
import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';

const base = 'http://127.0.0.1:3107';
const db = () => new DatabaseSync(path.resolve('..', 'db', 'pmw-smoke-run.sqlite'), { readOnly: true });

test('decision board places each visible requirement once, in its stored status column', async ({ page, context }) => {
  await context.addCookies([{ name: 'pmw_region', value: 'EU', url: base }]);
  await page.goto('/vehicles/G70?view=decisions');
  const con = db();
  try {
    const rows = con.prepare(`SELECT id, status FROM requirements WHERE vehicle='G70' AND markets LIKE '%"EU"%'`).all() as { id: string; status: string }[];
    await expect(page.getByTestId('decision-card')).toHaveCount(rows.length);
    for (const s of ['proposed', 'validate', 'edited', 'approved', 'rejected']) {
      await expect(page.getByTestId(`decision-${s}`).getByTestId('decision-card')).toHaveCount(rows.filter(r => r.status === s).length);
    }
    await expect(page.getByRole('navigation', { name: 'Views' }).getByRole('link', { name: 'Decisions', exact: true })).toHaveAttribute('aria-current', 'page');
  } finally { con.close(); }
});

test('moving a card runs the decision action with its reason, and the card can be reopened', async ({ page, context }) => {
  await context.addCookies([{ name: 'pmw_region', value: 'ALL', url: base }]);
  const con = db();
  const r = con.prepare("SELECT id, title FROM requirements WHERE vehicle='G60' AND kind='signal' AND status='proposed' ORDER BY priority ASC LIMIT 1").get() as { id: string; title: string };
  const status = () => (con.prepare('SELECT status FROM requirements WHERE id=?').get(r.id) as { status: string }).status;
  try {
    await page.goto('/vehicles/G60?view=decisions');
    const card = page.locator(`[data-testid="decision-card"][data-requirement-id="${r.id}"]`);
    await card.getByLabel(`Move ${r.title} to`).selectOption('rejected');
    const dialog = page.getByRole('dialog');
    await dialog.getByRole('button', { name: 'Confirm rejection' }).click();
    await expect(dialog.getByRole('alert')).toContainText('Add a short reason');
    await dialog.getByRole('textbox').fill('Covered by another requirement');
    await dialog.getByRole('button', { name: 'Confirm rejection' }).click();
    await expect(page.getByTestId('decision-rejected').locator(`[data-requirement-id="${r.id}"]`)).toBeVisible();
    expect(status()).toBe('rejected');
    const audit = con.prepare("SELECT rationale FROM audit_events WHERE entity_id=? AND action='rejected requirement' ORDER BY id DESC LIMIT 1").get(r.id) as { rationale: string };
    expect(audit.rationale).toBe('Covered by another requirement');

    // A decided card cannot jump straight to another decision; it is reopened first.
    const moved = page.locator(`[data-testid="decision-card"][data-requirement-id="${r.id}"]`);
    await moved.getByLabel(`Move ${r.title} to`).selectOption('approved');
    await expect(moved.getByRole('status')).toContainText('Move it to To Review (Reopen)');
    await moved.getByLabel(`Move ${r.title} to`).selectOption('proposed');
    await page.getByRole('dialog').getByRole('button', { name: 'Reopen' }).click();
    await expect(page.getByTestId('decision-proposed').locator(`[data-requirement-id="${r.id}"]`)).toBeVisible();
    expect(status()).toBe('proposed');
  } finally { con.close(); }
});

test('a card opens its Decision Card, and the board fits a phone', async ({ page, context }) => {
  await context.addCookies([{ name: 'pmw_region', value: 'ALL', url: base }]);
  await page.goto('/vehicles/G70?view=decisions');
  const first = page.getByTestId('decision-card').first();
  const id = await first.getAttribute('data-requirement-id');
  await first.getByRole('link').click();
  await expect(page).toHaveURL(new RegExp(`req=${id}`));
  await expect(page.getByRole('button', { name: 'Challenge', exact: true })).toBeVisible();
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('/vehicles/G70?view=decisions');
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBeLessThanOrEqual(390);
  await expect(page.getByTestId('decision-card').first()).toBeVisible();
});

