// Measures ElevenLabs agent turn latency: user text -> (tool calls via local PMW) -> first agent response.
const KEY = process.env.ELEVENLABS_API_KEY, AGENT = process.env.ELEVENLABS_AGENT_ID, APP = "http://127.0.0.1:3108";
const signed = await (await fetch(`https://api.elevenlabs.io/v1/convai/conversation/get-signed-url?agent_id=${AGENT}`, { headers: { "xi-api-key": KEY } })).json();
const ws = new WebSocket(signed.signed_url);
const turns = ["Open the 7 Series.", "What is the most important requirement there, and why?", "Show me the market conflicts for the 7 Series."];
let t0 = 0, firstAgent = 0, tools = [], idx = -1, started = false, lastSpoken = "";
const log = (...a) => console.log(...a);
function next() {
  idx++;
  if (idx >= turns.length) { ws.close(); return; }
  tools = []; firstAgent = 0; t0 = performance.now();
  ws.send(JSON.stringify({ type: "user_message", text: turns[idx] }));
}
ws.onopen = () => ws.send(JSON.stringify({ type: "conversation_initiation_client_data" }));
ws.onmessage = async (ev) => {
  const m = JSON.parse(ev.data);
  if (m.type === "ping") return ws.send(JSON.stringify({ type: "pong", event_id: m.ping_event.event_id }));
  if (m.type === "conversation_initiation_metadata") { log("connected"); return; }
  if (m.type === "agent_response") {
    const text = m.agent_response_event.agent_response;
    if (!started) { started = true; log(`greeting: "${text}"`); setTimeout(next, 300); return; }
    if (!firstAgent) firstAgent = performance.now();
    lastSpoken = text;
    log(`turn ${idx + 1} "${turns[idx]}"\n  tools: ${tools.map(t => `${t.name} ${t.ms}ms`).join(", ") || "none"}\n  first reply after ${Math.round(firstAgent - t0)} ms: "${text.slice(0, 160)}"`);
    setTimeout(next, 1500);
  }
  if (m.type === "client_tool_call") {
    const c = m.client_tool_call, ts = performance.now();
    const res = await fetch(`${APP}/api/voice/tools`, { method: "POST", headers: { Origin: APP, "Content-Type": "application/json", Cookie: "pmw_region=ALL" }, body: JSON.stringify({ tool: c.tool_name, params: c.parameters, spokenRequest: `latency test: ${turns[idx]}` }) });
    const body = await res.text();
    tools.push({ name: c.tool_name, ms: Math.round(performance.now() - ts) });
    ws.send(JSON.stringify({ type: "client_tool_result", tool_call_id: c.tool_call_id, result: body, is_error: !res.ok }));
  }
};
ws.onclose = () => log("closed");
setTimeout(() => { log("timeout"); process.exit(0); }, 90000);
EOF
