@keyframes in{from{transform:translateX(24px);opacity:0}to{transform:none;opacity:1}}
.drawer-bar{display:flex;align-items:center;justify-content:space-between;padding:12px 24px;border-bottom:1px solid var(--line)}
.close{width:36px;height:36px;border:1px solid var(--line);background:var(--white);font-size:20px;cursor:pointer}
.drawer-body{overflow:auto;padding:24px;display:flex;flex-direction:column;gap:20px}
.drawer h2{margin:0;font-size:28px;font-weight:300;line-height:1.15;text-wrap:balance}
