.scores div{background:var(--white);padding:12px 16px}.scores dt{font-size:12px;color:var(--ink-3)}.scores dd{margin:0;font-size:28px;font-weight:300;font-variant-numeric:tabular-nums}
.actions{display:flex;flex-wrap:wrap;gap:8px}
