<header class="top">
  <div class="wordmark"><b><i>P</i>MW</b><span>Product Minds on Wheels</span></div>
  <div class="region"><small>Your region</small><strong>All markets</strong></div>
  <span class="proto">for BMW Group · Hackathon Prototype</span>
</header>
<div class="shell">
  <nav class="side" aria-label="Main">
    <p class="eyebrow">Vehicles</p>
    <ul><li><a href="#" aria-current="page">7 Series</a></li><li><a href="#">5 Series</a></li><li><a href="#">1 Series</a></li></ul>
    <p class="eyebrow">Workspace</p>
    <ul><li><a href="#">Requirements board</a></li><li><a href="#">Cross-Model Radar</a></li><li><a href="#">Workflow</a></li><li><a href="#">Audit trail</a></li></ul>
  </nav>
  <main>
    <section class="hero">
      <p class="eyebrow" style="margin:0">Requirements for the successor generation · G70</p>
      <h1>BMW 7 Series</h1>
      <dl><div><dt>Viewing as</dt><dd>Head of product</dd></div><div><dt>Requirements</dt><dd id="h-total">20</dd></div><div><dt>Comments analysed</dt><dd>4,000</dd></div></dl>
    </section>
    <nav class="tabs" aria-label="Views">
      <a href="#">Requirements</a>
      <a href="#" aria-current="page">Priority board<span class="new">New</span></a>
      <a href="#">Decisions</a><a href="#">Decision matrix</a><a href="#">Signals</a><a href="#">Data health</a>
    </nav>
    <div class="content">
      <div class="board-head">
        <div>
          <h2>Priority board</h2>
          <p>Cards sit in the MoSCoW band their computed priority gives them. Drag a card to another band to override it with a reason; open a card for its evidence and assumptions.</p>
        </div>
        <div class="chips" role="group" aria-label="Filter">
          <button class="chip" id="f-all" aria-pressed="true" data-f="all">All<span id="n-all"></span></button>
          <button class="chip q" id="f-quick" aria-pressed="false" data-f="quick">Quick wins<span id="n-quick"></span></button>
          <button class="chip c" id="f-conflict" aria-pressed="false" data-f="conflict">Conflicts<span id="n-conflict"></span></button>
        </div>
      </div>
      <p class="note"><span><b>Design preview.</b> Real 7 Series requirements from the PMW database. Moves and buttons here are not saved; in the app every move is written to the audit trail.</span></p>
      <div class="lanes" id="lanes"></div>
    </div>
  </main>
</div>
<div id="drawer-slot"></div>
<dialog id="move-dialog" aria-labelledby="move-title">
  <h2 id="move-title">Move to Must have?</h2>
  <p id="move-text"></p>
  <label for="move-why">Reason for the override<textarea id="move-why" maxlength="500" placeholder="e.g. Board decision: connectivity is a brand promise for the 7 Series"></textarea></label>
  <p class="err" id="move-err" hidden>Add a short reason. It goes into the audit trail.</p>
  <div class="row"><button class="btn" id="move-cancel" type="button">Cancel</button><button class="btn primary" id="move-ok" type="button">Override priority band</button></div>
</dialog>
<div class="toast" id="toast" role="status" hidden></div>

<script>
const DATA = __DATA__;
const BANDS = [
  { key: "must", label: "Must have", hint: "Must shape the next generation", min: 65, color: "var(--must)" },
  { key: "should", label: "Should have", hint: "Strong case, plan for it", min: 55, color: "var(--should)" },
  { key: "could", label: "Could have", hint: "Include if it fits", min: 45, color: "var(--could)" },
  { key: "wont", label: "Won't have this time", hint: "Revisit for a later update", min: 0, color: "var(--wont)" },
];
const Q = { act: "Act", validate: "Validate first", monitor: "Monitor", park: "Park" };
const STATUS = { proposed: "Needs decision", approved: "Approved", rejected: "Rejected", validate: "Validation requested", edited: "Edited" };
const MARKET = { US: "United States", EU: "Europe", CN: "China", ROW: "Rest of World" };
const computed = (p) => BANDS.find((b) => p >= b.min).key;
const band = (k) => BANDS.find((b) => b.key === k);
const state = { filter: "all", open: null, menu: null, overrides: {}, pending: null };
const bandOf = (r) => state.overrides[r.id]?.to ?? computed(r.priority);
const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const visible = () => DATA.filter((r) => state.filter === "all" || (state.filter === "quick" ? r.kind === "quick_win" : r.kind === "market_conflict"));
const $ = (id) => document.getElementById(id);

function counts() {
  $("n-all").textContent = DATA.length;
  $("n-quick").textContent = DATA.filter((r) => r.kind === "quick_win").length;
  $("n-conflict").textContent = DATA.filter((r) => r.kind === "market_conflict").length;
}

function cardHTML(r) {
  const o = state.overrides[r.id];
  const flags = [
    r.kind === "quick_win" ? '<span class="flag f-quick">Quick win</span>' : "",
    r.kind === "market_conflict" ? '<span class="flag f-conflict">Market conflict</span>' : "",
    o ? `<span class="flag f-override" title="${esc(o.why)}">PM override · was ${band(computed(r.priority)).label}</span>` : "",
  ].join("");
  const menu = state.menu === r.id ? `<div class="menu" role="menu" aria-label="Move ${esc(r.title)} to">${BANDS.filter((b) => b.key !== bandOf(r)).map((b) => `<button role="menuitem" data-move="${b.key}" data-id="${r.id}"><i style="background:${b.color}"></i>Move to ${b.label}</button>`).join("")}</div>` : "";
  return `<li><article class="card" draggable="true" data-id="${r.id}" aria-current="${state.open === r.id}">
    <div class="card-top">
      <button class="card-title" data-open="${r.id}">${esc(r.title)}</button>
      <div class="score"><b>${r.priority}</b><small>Priority</small></div>
      <button class="more" data-menu="${r.id}" aria-haspopup="menu" aria-expanded="${state.menu === r.id}" aria-label="Move ${esc(r.title)}">⋯</button>
    </div>
    ${r.part ? `<div class="part">${esc(r.part)}</div>` : ""}
    <div class="meta"><span class="badge b-${r.quadrant}">${Q[r.quadrant]}</span>${flags}<span class="conf">Confidence ${r.confidence}</span></div>
    ${menu}
  </article></li>`;
}

function render() {
  counts();
  const rows = visible();
  $("lanes").innerHTML = BANDS.map((b) => {
    const items = rows.filter((r) => bandOf(r) === b.key).sort((x, y) => y.priority - x.priority);
    return `<section class="lane" data-band="${b.key}" style="--lc:${b.color}" aria-labelledby="lane-${b.key}">
      <div class="lane-head"><h3 id="lane-${b.key}">${b.label}</h3><span>${items.length}</span></div>
      <div class="lane-hint">${b.hint} · priority ${b.key === "wont" ? "below 45" : b.key === "must" ? "65+" : `${b.min}–${b.min + 9}`}</div>
      <ul class="cards">${items.map(cardHTML).join("") || '<li class="empty">Drop a card here</li>'}</ul>
    </section>`;
  }).join("");
  document.querySelectorAll("[data-f]").forEach((c) => c.setAttribute("aria-pressed", c.dataset.f === state.filter));
  renderDrawer();
}

function mixRow(mix) {
  if (!mix) return '<p style="margin:0;font-size:13px;color:var(--ink-3)">Evidence mix pending.</p>';
  const parts = [["observed", "Observed comments", "var(--m-observed)"], ["survey", "Survey measures", "var(--m-survey)"], ["inferred", "AI inference", "var(--m-inferred)"], ["assumed", "Assumptions", "var(--m-assumed)"]];
  return `<div class="mix" role="img" aria-label="Evidence mix">${parts.map(([k, , c]) => `<span style="width:${(mix[k] * 100).toFixed(1)}%;background:${c}"></span>`).join("")}</div>
    <ul class="legend">${parts.map(([k, l, c]) => `<li><i style="background:${c}"></i>${l}<b>${Math.round(mix[k] * 100)}%</b></li>`).join("")}</ul>`;
}

function renderDrawer() {
  const r = DATA.find((x) => x.id === state.open);
  if (!r) { $("drawer-slot").innerHTML = ""; return; }
  const b = band(bandOf(r)), o = state.overrides[r.id];
  const thr = { p: 55, c: 58 };
  const why = `${Q[r.quadrant]}: priority ${r.priority} ${r.priority >= thr.p ? "≥" : "<"} ${thr.p} and confidence ${r.confidence} ${r.confidence >= thr.c ? "≥" : "<"} ${thr.c}.`;
  $("drawer-slot").innerHTML = `<div class="drawer-root">
    <button class="drawer-backdrop" data-close aria-label="Close requirement"></button>
    <aside class="drawer" role="dialog" aria-label="${esc(r.title)}" tabindex="-1">
      <div class="drawer-bar"><span class="eyebrow">Requirement</span><button class="close" data-close aria-label="Close requirement">×</button></div>
      <div class="drawer-body">
        <div class="chiprow"><span class="mb" style="background:${b.color}">${b.label}</span><span class="badge b-${r.quadrant}">${Q[r.quadrant]}</span><span class="status">${STATUS[r.status] ?? r.status}</span>${o ? '<span class="flag f-override">PM override</span>' : ""}</div>
        <div><h2>${esc(r.title)}</h2><p class="mono" style="margin:6px 0 0;color:var(--ink-3)">${r.id}${r.part ? ` · ${esc(r.part)}` : ""}</p></div>
        <p class="why"><b>Why the AI recommends this.</b> ${why}${o ? ` <b>Band overridden by the PM:</b> “${esc(o.why)}”` : ""}</p>
        <dl class="scores"><div><dt>Priority</dt><dd>${r.priority}</dd></div><div><dt>Confidence</dt><dd>${r.confidence}</dd></div></dl>
        <div class="actions"><button class="btn primary" data-mock>Approve</button><button class="btn" data-mock>Validate first</button><button class="btn" data-mock>Edit</button><button class="btn" data-mock>Reject</button><button class="btn challenge" data-mock>Challenge</button></div>
        <section class="section"><h3>Evidence &amp; assumptions</h3><div class="in">${mixRow(r.mix)}</div></section>
        <section class="section"><h3>Customer evidence</h3><div class="in">
          ${r.quotes.length ? r.quotes.map((q) => `<blockquote class="quote">“${esc(q.text)}${q.text.length >= 220 ? "…" : ""}”<footer><span class="mono">${q.id}</span> · ${MARKET[q.market] ?? q.market}</footer></blockquote>`).join("") : '<p style="margin:0;font-size:13px;color:var(--ink-3)">No customer comments. This requirement rests on survey evidence only.</p>'}
        </div></section>
        <section class="section"><h3>Requirement</h3><div class="in"><p style="margin:0">${esc(r.requirement)}</p><p style="margin:0;font-size:13px;color:var(--ink-3)"><b style="color:var(--ink-2)">Customer need.</b> ${esc(r.need)}</p></div></section>
        <section class="section"><h3>Assumptions and uncertainties</h3><div class="in"><ul class="list">
          ${r.assumptions.map((a) => `<li><span class="tag t-ass">Assumption</span>${esc(a)}</li>`).join("")}
          ${r.uncertainties.map((a) => `<li><span class="tag t-unc">Uncertainty</span>${esc(a)}</li>`).join("")}
        </ul></div></section>
      </div>
    </aside></div>`;
}

function toast(msg) { const t = $("toast"); t.textContent = msg; t.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => (t.hidden = true), 3200); }

function requestMove(id, to) {
  const r = DATA.find((x) => x.id === id);
  if (!r || bandOf(r) === to) return;
  state.menu = null;
  if (to === computed(r.priority)) { delete state.overrides[id]; render(); toast(`${r.title} is back in ${band(to).label}, matching its priority ${r.priority}.`); return; }
  state.pending = { id, to };
  $("move-title").textContent = `Move to ${band(to).label}?`;
  $("move-text").textContent = `Priority ${r.priority} puts “${r.title}” in ${band(computed(r.priority)).label}. Moving it overrides the band; the score stays ${r.priority} and your reason is recorded in the audit trail.`;
  $("move-why").value = ""; $("move-err").hidden = true;
  $("move-dialog").showModal();
}

$("move-ok").addEventListener("click", () => {
  const why = $("move-why").value.trim();
  if (!why) { $("move-err").hidden = false; return; }
  const { id, to } = state.pending; state.overrides[id] = { to, why }; state.pending = null;
  $("move-dialog").close(); render();
  toast(`Moved to ${band(to).label}. In the app this is logged with your reason.`);
});
$("move-cancel").addEventListener("click", () => $("move-dialog").close());

document.addEventListener("click", (e) => {
  const t = e.target.closest("button"); if (!t) { if (state.menu) { state.menu = null; render(); } return; }
  if (t.dataset.f) { state.filter = t.dataset.f; render(); return; }
  if (t.dataset.open) { state.open = t.dataset.open; state.menu = null; render(); document.querySelector(".drawer")?.focus(); return; }
  if (t.dataset.menu) { state.menu = state.menu === t.dataset.menu ? null : t.dataset.menu; render(); return; }
  if (t.dataset.move) { requestMove(t.dataset.id, t.dataset.move); return; }
  if ("close" in t.dataset) { state.open = null; render(); return; }
  if ("mock" in t.dataset) toast(`${t.textContent} works in the app. This preview does not save decisions.`);
});
document.addEventListener("keydown", (e) => { if (e.key === "Escape" && state.open && !$("move-dialog").open) { state.open = null; render(); } });

let dragId = null;
document.addEventListener("dragstart", (e) => { const c = e.target.closest(".card"); if (!c) return; dragId = c.dataset.id; c.classList.add("dragging"); e.dataTransfer.effectAllowed = "move"; e.dataTransfer.setData("text/plain", dragId); });
document.addEventListener("dragend", () => { dragId = null; document.querySelectorAll(".dragging,.over").forEach((n) => n.classList.remove("dragging", "over")); });
document.addEventListener("dragover", (e) => { const l = e.target.closest(".lane"); if (!l || !dragId) return; e.preventDefault(); document.querySelectorAll(".lane.over").forEach((n) => n !== l && n.classList.remove("over")); l.classList.add("over"); });
document.addEventListener("drop", (e) => { const l = e.target.closest(".lane"); if (!l || !dragId) return; e.preventDefault(); const id = dragId; l.classList.remove("over"); requestMove(id, l.dataset.band); });

// Open the top requirement so the first view shows the evidence panel.
state.open = DATA[0]?.id ?? null;
render();
</script>
